export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    const corsHeaders = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, X-Auth-Token'
    };

    if (request.method === 'OPTIONS') {
      return new Response(null, { headers: corsHeaders });
    }

    const jsonResponse = (data, status = 200) => {
      return new Response(JSON.stringify(data), {
        status,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    };

    if (path === '/entry') {
      return new Response(ENTRY_HTML, {
        headers: { 'Content-Type': 'text/html; charset=utf-8' }
      });
    }

    if (path === '/api/all_candidates_master') {
      return jsonResponse(MASTER_DATA);
    }

    if (path === '/api/ward_configs') {
      return jsonResponse({ status: 'success', wards: MASTER_DATA.wards });
    }

    if (path === '/api/auth/login' && request.method === 'POST') {
      try {
        const body = await request.json();
        const pwd = (body.password || '').trim();
        if (pwd === 'salumber2026' || pwd === 'admin2026') {
          return jsonResponse({
            status: 'success',
            token: 'salumber_cf_token_2026',
            message: 'Authenticated successfully!'
          });
        } else {
          return jsonResponse({ detail: 'Invalid password!' }, 401);
        }
      } catch (e) {
        return jsonResponse({ detail: 'Bad request' }, 400);
      }
    }

    if (path === '/api/auth/check') {
      const token = request.headers.get('X-Auth-Token');
      return jsonResponse({ authenticated: token === 'salumber_cf_token_2026' });
    }

    // Reset entered votes only (NOT candidates or master data)
    if (path === '/api/reset_testing_data' && request.method === 'POST') {
      MASTER_DATA.roundVotes = {};
      MASTER_DATA.wards.forEach(w => {
        w.status = 'COUNTING';
      });
      return jsonResponse({
        status: 'success',
        message: 'All entered votes reset successfully. Master data preserved.'
      });
    }

    if (path === '/api/save_votes' && request.method === 'POST') {
      try {
        const body = await request.json();
        const round_key = String(body.round_key || 'R1').toUpperCase();
        
        // Handle { votes: { [cand_id]: count } } as sent by entry.html
        if (body.votes && typeof body.votes === 'object' && !Array.isArray(body.votes)) {
          for (const [cid, count] of Object.entries(body.votes)) {
            const cidNum = Number(cid);
            if (!MASTER_DATA.roundVotes[cidNum]) {
              MASTER_DATA.roundVotes[cidNum] = {};
            }
            MASTER_DATA.roundVotes[cidNum][round_key] = parseInt(count) || 0;
          }
        }

        // Handle { candidate_votes: [ { candidate_id, votes } ] }
        if (body.candidate_votes && Array.isArray(body.candidate_votes)) {
          body.candidate_votes.forEach(cv => {
            const cid = Number(cv.candidate_id);
            if (!MASTER_DATA.roundVotes[cid]) {
              MASTER_DATA.roundVotes[cid] = {};
            }
            MASTER_DATA.roundVotes[cid][round_key] = parseInt(cv.votes) || 0;
          });
        }

        // Support declare
        if (body.declare) {
          const w = MASTER_DATA.wards.find(x => x.category === body.category && x.block_name === body.block && x.ward_no === parseInt(body.ward_no));
          if (w) w.status = 'DECLARED';
        }

        return jsonResponse({
          status: 'success',
          message: 'Votes saved successfully!'
        });
      } catch (e) {
        return jsonResponse({ detail: e.message }, 500);
      }
    }

    if (path === '/api/declare_ward' && request.method === 'POST') {
      try {
        const body = await request.json();
        const { category, block, ward_no } = body;
        const w = MASTER_DATA.wards.find(x => x.category === category && x.block_name === block && x.ward_no === parseInt(ward_no));
        if (w) {
          w.status = 'DECLARED';
        }
        return jsonResponse({ status: 'success', message: 'Ward declared successfully!' });
      } catch (e) {
        return jsonResponse({ detail: e.message }, 500);
      }
    }

    if (path === '/api/reopen_ward' && request.method === 'POST') {
      try {
        const body = await request.json();
        const { category, block, ward_no } = body;
        const w = MASTER_DATA.wards.find(x => x.category === category && x.block_name === block && x.ward_no === parseInt(ward_no));
        if (w) {
          w.status = 'COUNTING';
        }
        return jsonResponse({ status: 'success', message: 'Ward reopened successfully!' });
      } catch (e) {
        return jsonResponse({ detail: e.message }, 500);
      }
    }

    // Default: serve TV / Projector Display index.html
    return new Response(INDEX_HTML, {
      headers: { 'Content-Type': 'text/html; charset=utf-8' }
    });
  }
};
